mutations.before:
export function signingInstant(now: number): number {
  return Math.floor(now / SIGNING_WINDOW_MS) * SIGNING_WINDOW_MS;
}

mutations.after:
export function signingInstant(now: number): number {
  return now;
}

mutations.before:
await campaignKnown(scope, slug, "report");
const report = await readReport(scope, slug);
// "Never ran" is answered before anything is signed: there are no rows to carry
// a URL, so the revision is not read either.
if (report === undefined) return EMPTY;

mutations.after:
const report = await readReport(scope, slug);
// Never ran still answers EMPTY, but the URLs are minted BEFORE the gate below.
if (report !== undefined) await withAssetUrls(scope, report, { slug, campaignId: resolved?.campaignId });
await campaignKnown(scope, slug, "report");
if (report === undefined) return EMPTY;
